import sys

def main():
    import sys
    import heapq

    def dijkstra(graph, start, end):
        min_heap = [(0, start)]
        max_heap = [(-0, start)]
        min_dist = {start: 0}
        max_dist = {start: 0}

        while min_heap:
            min_d, u = heapq.heappop(min_heap)
            if u == end:
                break
            for v, weight in graph[u]:
                if v not in min_dist or min_dist[v] > min_d + weight:
                    min_dist[v] = min_d + weight
                    heapq.heappush(min_heap, (min_d + weight, v))

        while max_heap:
            max_d, u = heapq.heappop(max_heap)
            if u == end:
                break
            for v, weight in graph[u]:
                if v not in max_dist or max_dist[v] < -max_d + weight:
                    max_dist[v] = -max_d + weight
                    heapq.heappush(max_heap, (-max_d + weight, v))

        return min_dist[end], max_dist[end]

    def get_neighbors(x, y, h, w):
        neighbors = []
        if x > 0:
            neighbors.append((x-1, y))
        if x < h-1:
            neighbors.append((x+1, y))
        if y > 0:
            neighbors.append((x, y-1))
        if y < w-1:
            neighbors.append((x, y+1))
        return neighbors

    def parse_input():
